import React, { useEffect, useState } from 'react';
import { recruiterApi, templateApi } from '../services/api';
import { downloadResume } from '../utils/downloadResume';
import { useToast } from '../components/Toast';
import ResumeDocumentPreview from '../components/ResumeDocumentPreview';

const SUGGESTED_TAGS = ['React', 'Java', 'Marketing', 'Product Manager', 'Python', 'Full Stack', 'Design', 'Data'];

export default function RecruiterSearch() {
  const [keyword, setKeyword] = useState('');
  const [results, setResults] = useState([]);
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(false);
  const [previewCandidate, setPreviewCandidate] = useState(null);
  const { addToast } = useToast();

  const loadAllCandidates = () => {
    setLoading(true);
    Promise.all([
      recruiterApi.getCandidates().catch(() => ({ data: [] })),
      templateApi.getAll().catch(() => ({ data: [] }))
    ]).then(([candRes, tempRes]) => {
      setResults(candRes.data || []);
      setTemplates(tempRes.data || []);
    }).finally(() => setLoading(false));
  };

  useEffect(() => { loadAllCandidates(); }, []);

  const handleSearch = async (queryToSearch) => {
    const term = typeof queryToSearch === 'string' ? queryToSearch : keyword;
    if (!term.trim()) {
      loadAllCandidates();
      return;
    }
    setLoading(true);
    try {
      const res = await recruiterApi.search(term.trim());
      setResults(res.data || []);
      addToast(`Found ${(res.data || []).length} candidate(s)`, 'info', 2000);
    } catch (err) {
      addToast('Search error', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleTagClick = (tag) => {
    setKeyword(tag);
    handleSearch(tag);
  };

  const handleDownload = (r) => {
    addToast(`Downloading ${r.candidateName || 'candidate'}'s resume…`, 'info');
    downloadResume(r);
  };

  const getInitials = (name) => {
    if (!name) return 'C';
    const parts = name.trim().split(' ');
    if (parts.length >= 2) return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
    return name.slice(0, 2).toUpperCase();
  };

  return (
    <div className="page-container recruiter-search-page">
      {/* Header */}
      <div className="recruiter-header-banner">
        <div className="header-badge">🎯 Verified Talent Directory</div>
        <h1>Candidate Search</h1>
        <p className="muted-lead">
          Browse vetted job seekers who have actively shared their resumes with employers and recruiters.
        </p>
      </div>

      {/* Interactive Search Bar */}
      <form onSubmit={(e) => { e.preventDefault(); handleSearch(); }} className="recruiter-search-form">
        <div className="search-box-composite">
          <span className="search-composite-icon">🔍</span>
          <input
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            placeholder="Search candidates by name, skills (e.g. React, Python), headline, or city…"
          />
          {keyword && (
            <button
              type="button"
              className="clear-search-btn"
              onClick={() => { setKeyword(''); loadAllCandidates(); }}
            >
              ×
            </button>
          )}
          <button type="submit" className="btn-search-submit" disabled={loading}>
            {loading ? 'Searching…' : 'Find Candidates'}
          </button>
        </div>
      </form>

      {/* Suggested Filter Tag Chips */}
      <div className="suggested-tags-wrapper">
        <span className="tags-label">Popular Searches:</span>
        <div className="tags-chips-list">
          {SUGGESTED_TAGS.map((tag) => (
            <button
              key={tag}
              type="button"
              className={`tag-chip-btn ${keyword.toLowerCase() === tag.toLowerCase() ? 'active' : ''}`}
              onClick={() => handleTagClick(tag)}
            >
              {tag}
            </button>
          ))}
          {keyword && (
            <button
              type="button"
              className="tag-chip-btn clear"
              onClick={() => { setKeyword(''); loadAllCandidates(); }}
            >
              Reset Filters ↺
            </button>
          )}
        </div>
      </div>

      {/* Status / Count */}
      <div className="candidates-count-bar">
        <span>Showing <strong>{results.length}</strong> verified candidate profile{results.length === 1 ? '' : 's'}</span>
      </div>

      {loading && (
        <div className="loading-state-container">
          <div className="spinner"></div>
          <p>Searching candidate database…</p>
        </div>
      )}

      {!loading && results.length === 0 && (
        <div className="empty-state-card">
          <div className="empty-state-art">🔍</div>
          <h3>No matching candidates found</h3>
          <p>Try searching with different skill keywords or clear your query to view all available candidates.</p>
          <button className="btn-secondary" onClick={() => { setKeyword(''); loadAllCandidates(); }}>
            View All Candidates
          </button>
        </div>
      )}

      {/* Candidate Grid */}
      <div className="candidate-grid">
        {results.map((r) => (
          <div className="candidate-card-pro" key={r.id}>
            <div className="candidate-top-meta">
              <div className="candidate-avatar">
                {getInitials(r.candidateName)}
              </div>
              <div className="candidate-name-box">
                <h3>{r.candidateName || 'Verified Candidate'}</h3>
                <p className="candidate-headline">{r.headline || r.title || 'Professional Specialist'}</p>
                {r.location && <span className="candidate-location">📍 {r.location}</span>}
              </div>
            </div>

            <p className="candidate-summary-snippet">
              {r.summary ? `${r.summary.slice(0, 150)}${r.summary.length > 150 ? '…' : ''}` : 'No candidate summary provided.'}
            </p>

            <div className="candidate-skills-tray">
              {(r.skills || []).slice(0, 5).map((s) => (
                <span key={s} className="candidate-skill-pill">{s}</span>
              ))}
              {(r.skills || []).length > 5 && (
                <span className="candidate-skill-more">+{r.skills.length - 5} more</span>
              )}
            </div>

            <div className="candidate-card-actions">
              <button
                type="button"
                className="btn-candidate-preview"
                onClick={() => setPreviewCandidate(r)}
              >
                👁️ View Live Sheet
              </button>
              <button
                type="button"
                className="btn-candidate-download"
                onClick={() => handleDownload(r)}
                title="Download / Print PDF"
              >
                📥 Download PDF
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Candidate Live Resume Modal */}
      {previewCandidate && (
        <div className="modal-overlay" onClick={() => setPreviewCandidate(null)}>
          <div className="modal-container preview-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <div className="modal-title-box">
                <h3>{previewCandidate.candidateName || 'Candidate Resume'}</h3>
                <span className="modal-template-tag">
                  {previewCandidate.headline || 'Resume Document'}
                </span>
              </div>
              <div className="modal-actions-right">
                <button
                  type="button"
                  className="btn-primary btn-sm"
                  onClick={() => handleDownload(previewCandidate)}
                >
                  📥 Download Resume PDF
                </button>
                <button
                  type="button"
                  className="modal-close-btn"
                  onClick={() => setPreviewCandidate(null)}
                >
                  ✕
                </button>
              </div>
            </div>
            <div className="modal-body-scroller">
              <div className="modal-preview-wrapper">
                <ResumeDocumentPreview
                  resume={previewCandidate}
                  template={templates.find((t) => Number(t.id) === Number(previewCandidate.templateId))}
                />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
